<div class="grid grid-cols-1 gap-5 md:grid-cols-2">
    <div class="md:col-span-2"><label class="mb-1 block text-sm font-medium text-gray-700">Proyecto <span class="text-red-600">*</span></label><select id="proyecto_id" name="proyecto_id" required class="w-full rounded-md border-gray-300"><option value="">Seleccione un proyecto</option>@foreach($proyectos as $proyecto)<option value="{{ $proyecto->id }}" data-aprobado="{{ $proyecto->presupuesto_aprobado }}" @selected((string)old('proyecto_id',$registro?->proyecto_id ?? request('proyecto_id'))===(string)$proyecto->id)>{{ $proyecto->codigo }} - {{ $proyecto->nombre }} | Aprobado: USD {{ number_format((float)$proyecto->presupuesto_aprobado,2) }}</option>@endforeach</select><x-input-error :messages="$errors->get('proyecto_id')" class="mt-1" /></div>
