<script>document.addEventListener('DOMContentLoaded',()=>{const p=document.getElementById('proyecto_id'),v=document.getElementById('presupuesto_vigente'),t=document.getElementById('aprobadoProyecto');const actualizar=()=>{const o=p.options[p.selectedIndex],m=o?.dataset.aprobado;if(m){t.textContent='USD '+Number(m).toLocaleString('es-EC',{minimumFractionDigits:2});if(!v.value)v.value=Number(m).toFixed(2)}else t.textContent='Seleccione un proyecto'};p.addEventListener('change',actualizar);actualizar()});</script>
